@WebSocketGateway({ namespace: "terminal", cors: { origin: "*" } })
export class TerminalGateway {
  @SubscribeMessage("execute-command")
  handleCommand(@MessageBody() cmd: string) {
    return { event: "terminal-output", data: `Ejecutando: ${cmd}\n` };
  }
}

export function useTerminalSocket() {
  const [output, setOutput] = useState<string[]>([]);
  const socketRef = useRef<Socket | null>(null);

  useEffect(() => {
    socketRef.current = io("/terminal");
    socketRef.current.on("terminal-output", (data) => {
      setOutput((prev) => [...prev, data]);
    });
    return () => { socketRef.current?.disconnect(); };
  }, []);

  const sendCommand = (cmd: string) => {
    socketRef.current?.emit("execute-command", cmd);
  };

  return { output, sendCommand };
}

